private fun decode(parts: List<String>): ByteArray = Base64.getDecoder().decode(parts.joinToString(""))

@Suppress("unused")
val instaPrimeV8CorePatch = resourcePatch(
    name = "InstaPrime v8 full mod (beta 2)",
    description = "Applies the prebuilt InstaPrime V8 core and customizes the in-app texts.",
) {
    compatibleWith(
        Compatibility(
            name = "InstaPrime",
            packageName = "com.instaprime.android",
            targets = listOf(AppTarget(version = "451.0.0.53.80")),
        ),
    )

    execute {
        get(CORE23_ASSET).writeBytes(decode(CORE23))

        // Changelog fixo (sem consultar o servidor).
        get(CLOGS_ASSET).writeText(CLOGS)

        val en = get(EN_ASSET)
        var text = en.readText()

        text = text.replace(
            "\"social_category\": \"Follow us for latest updates\"",
            "\"social_category\": \"Wagg13 Mods\"",
        )
        text = text.replace(
            "\"clone_label\": \"Clone\"",
            "\"clone_label\": \"Clone PREMIUM\"",
        )
        text = text.replace(
            "Made with \u2764 by Ravi Varma",
            "Cracked by Wagg13 \u2014 t.me/wagg13mods",
        )

        en.writeText(text)
    }
}
